CREATE TABLE "app"."acceptance_contracts" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "app"."acceptance_contracts_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9007199254740991 START WITH 1 CACHE 1),
	"work_item_id" bigint,
	"change_id" bigint,
	"version" integer NOT NULL,
	"criteria" jsonb NOT NULL,
	"source" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	CONSTRAINT "acceptance_contracts_version_check" CHECK (version > 0),
	CONSTRAINT "acceptance_contracts_owner_check" CHECK ((work_item_id IS NOT NULL) OR (change_id IS NOT NULL)),
