CREATE TABLE "app"."factory_runs" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "app"."factory_runs_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9007199254740991 START WITH 1 CACHE 1),
	"repository_id" bigint NOT NULL,
	"work_item_id" bigint,
	"change_id" bigint,
	"profile_key" text NOT NULL,
	"start_stage" text NOT NULL,
	"stop_after_stage" text NOT NULL,
	"policy_snapshot" jsonb NOT NULL,
	"trigger" text NOT NULL,
	"actor" text,
	"status" text DEFAULT 'active' NOT NULL,
	"handoff_reason" text,
	"idempotency_key" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"completed_at" timestamp with time zone,
	CONSTRAINT "factory_runs_idempotency_key_unique" UNIQUE("idempotency_key"),
	CONSTRAINT "factory_runs_status_check" CHECK (status = ANY (ARRAY['active'::text, 'awaiting_human'::text, 'handed_off'::text, 'completed'::text, 'failed'::text, 'cancelled'::text])),
	CONSTRAINT "factory_runs_profile_check" CHECK (profile_key = ANY (ARRAY['review_on_demand'::text, 'automatic_review'::text, 'review_and_repair'::text, 'idea_to_pr'::text, 'assisted_delivery'::text, 'full_delivery'::text, 'native_turnkey'::text, 'legacy_factory'::text])),
	CONSTRAINT "factory_runs_stage_check" CHECK (start_stage = ANY (ARRAY['plan'::text, 'implement'::text, 'publish'::text, 'review'::text, 'repair'::text, 'verify'::text, 'merge'::text]) AND stop_after_stage = ANY (ARRAY['plan'::text, 'implement'::text, 'publish'::text, 'review'::text, 'repair'::text, 'verify'::text, 'merge'::text])),
	CONSTRAINT "factory_runs_stage_order_check" CHECK (array_position(ARRAY['plan'::text, 'implement'::text, 'publish'::text, 'review'::text, 'repair'::text, 'verify'::text, 'merge'::text], start_stage) <= array_position(ARRAY['plan'::text, 'implement'::text, 'publish'::text, 'review'::text, 'repair'::text, 'verify'::text, 'merge'::text], stop_after_stage)),
	CONSTRAINT "factory_runs_policy_object_check" CHECK (jsonb_typeof(policy_snapshot) = 'object'::text)
);
