CREATE TABLE "app"."lifecycle_events" (
	"idempotency_key" text PRIMARY KEY NOT NULL,
	"factory_run_id" bigint,
	"change_id" bigint,
	"kind" text NOT NULL,
	"payload" jsonb,
	"decision" jsonb,
