CREATE TABLE "app"."stage_runs" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "app"."stage_runs_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9007199254740991 START WITH 1 CACHE 1),
	"factory_run_id" bigint NOT NULL,
	"change_id" bigint,
	"stage" text NOT NULL,
	"attempt" integer DEFAULT 1 NOT NULL,
	"status" text DEFAULT 'queued' NOT NULL,
	"trigger" text NOT NULL,
	"input" jsonb,
	"output" jsonb,
	"workflow_instance" text,
	"error" text,
	"idempotency_key" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"started_at" timestamp with time zone,
	"completed_at" timestamp with time zone,
	CONSTRAINT "stage_runs_idempotency_key_unique" UNIQUE("idempotency_key"),
	CONSTRAINT "stage_runs_attempt_unique" UNIQUE("factory_run_id","stage","attempt"),
	CONSTRAINT "stage_runs_attempt_check" CHECK (attempt > 0),
	CONSTRAINT "stage_runs_status_check" CHECK (status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text, 'cancelled'::text])),
	CONSTRAINT "stage_runs_stage_check" CHECK (stage = ANY (ARRAY['plan'::text, 'implement'::text, 'publish'::text, 'review'::text, 'repair'::text, 'verify'::text, 'merge'::text]))
);
